var st = [[0,105,125,0],[150,125,105,2048],[255,150,50,4096]], i, g = new ActionDescriptor(); g.putString(C2T('Nm  '), 'plan'); g.putEnumerated(C2T('GrdF'), C2T('GrdF'), C2T('CstS')); g.putDouble(C2T('Intr'), 4096);
